<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teller Summary</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>@media print{nav,.filters,.no-print{display:none!important}body{background:#fff}.container{max-width:none}}</style></head><body class="bg-light"><main class="container py-4"><nav class="mb-3"><a href="<?= base_url('reports') ?>">Reports</a> / Teller Summary</nav><h1 class="h3">Cashier / Teller Report</h1><form class="row g-2 my-3 filters"><div class="col-auto"><label class="form-label">Date</label><input class="form-control" type="date" name="date" value="<?= esc($date) ?>"></div><div class="col-auto align-self-end"><button class="btn btn-primary">Filter</button><button type="button" class="btn btn-outline-secondary" onclick="window.print()">Print Report</button></div></form><p><span class="badge text-bg-primary">Total Count: <?= number_format($totalCount) ?></span> <span class="badge text-bg-success">Total Processed: Rs. <?= number_format($totalAmount,2) ?></span></p><div class="table-responsive bg-white"><table class="table table-striped"><thead><tr><th>Teller</th><th>Transactions</th><th>Deposits (LKR)</th><th>Withdrawals (LKR)</th><th>Processed (LKR)</th></tr></thead><tbody><?php foreach($summary as $row): ?><tr><td><?= esc($row['teller_name']) ?></td><td><?= number_format($row['transaction_count']) ?></td><td>Rs. <?= number_format($row['deposit_total'],2) ?></td><td>Rs. <?= number_format($row['withdrawal_total'],2) ?></td><td>Rs. <?= number_format($row['deposit_total']+$row['withdrawal_total'],2) ?></td></tr><?php endforeach ?><?php if(!$summary): ?><tr><td colspan="5" class="text-center text-secondary">No teller activity found.</td></tr><?php endif ?></tbody></table></div></main></body></html>
